def merge_dicts(a, b):
    # Create a copy of dictionary b to avoid modifying it directly
    merged_dict = dict(b)

    # Update the merged dictionary with all key-value pairs from dictionary a
    for key, value in a.items():
        if key in merged_dict:
            merged_dict[key] = value  # Overwrite the existing value if the key exists
        else:
            merged_dict[key] = value

    return merged_dict

